        "If no valid flight or hotel options exist, clearly state that no itinerary fits.",
        "Do not book or reserve anything."
      ]
    }
  ],
  "tasks": [
    {
      "id": "search_and_plan",
      "agent_id": "planner",
      "type": "search_and_itinerary_build",
      "description": "Search for flights and hotels for the requested dates and preferences, then build a day-by-day itinerary covering the full trip only from returned results. Compute the total cost from returned itemized prices.",
      "tool_requirements": [
        "flight_search",
        "hotel_search"
      ],
      "constraints": [
        "Use live lookup data only.",
        "Include only returned prices and availability.",
        "Cover every day from depart_date through return_date.",
        "If no combination fits the budget, return a clear no-fit statement.",
        "Do not include any booking action."
      ],
      "final_response_requirements": [
        "day_by_day_itinerary",
        "itemized_costs",
        "total_cost",
        "explicit_approval_request_before_booking",
        "or clear no_itinerary_fits_budget_statement"
      ]
    }
  ],
  "policies": {
    "booking_gate": {
      "enabled": true,
      "rule": "No booking or reservation action may occur unless the user explicitly approves after reviewing the proposed itinerary."
    },
    "data_integrity": {
      "enabled": true,
      "rule": "Prices, availability, and cancellation/meal details must come only from returned search data."
    },
    "budget_handling": {
      "enabled": true,
      "rule": "If the returned options do not fit the budget, state that clearly and do not fabricate an alternative."
    }
  }
}
